84	// tc_train_step: one Fork-B TC step. params [total] fp32 (updated in place);
85	// tokens [B,kSeq] int32; targets [B] int32; state [3*total] fp32 ([m|v|extra]).
86	// Returns {loss (cpu float scalar), grad [total] fp32 (the reduced grad)}.
87	static std::vector<torch::Tensor> tc_train_step(
88	        torch::Tensor params, torch::Tensor tokens, torch::Tensor targets,
89	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
90	        double weight_decay, double bc1, double bc2, int64_t step,
91	        int64_t ncta_cap) {
92	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
93	    TORCH_CHECK(params.numel() == kMambaTotalElems, "params must be the flat mamba blob (", kMambaTotalElems, ")");
94	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
95	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
96	    const int B = (int)targets.numel();
97	    TORCH_CHECK(tokens.numel() == (int64_t)B * mb::kSeq, "tokens must be [B,kSeq]");
98	    TORCH_CHECK((B % 16) == 0, "TC path requires B %% 16 == 0 (dW K-loop is 16-step atoms)");
99	    const int64_t total = kMambaTotalElems;
100	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
101	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
102	
103	    const int nCTA = tc_effective_nctas(params, (int)ncta_cap);
104	    TcScratch& sc = tc_scratch_for(params, B, nCTA);
105	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
106	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
107	
108	    PersistentContext ctx{
109	        sc.g_next.data_ptr<int>(),
110	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
111	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
112	        ::sg::fused::sm90::kMambaNumTensors,
113	        0u};
114	
115	    FusedOptState st;
116	    float* m = state.data_ptr<float>();
117	    st.exp_avg = m;
118	    st.exp_avg_sq = m + total;
119	    st.lr = (float)lr; st.beta1 = (float)beta1; st.beta2 = (float)beta2;
120	    st.eps = (float)eps; st.wd = (float)weight_decay;
121	    st.bc1 = (float)bc1; st.bc2 = (float)bc2;
122	
123	    MambaTokenCtx tok;
124	    tok.tokens = tokens.data_ptr<int>();
125	    tok.targets = targets.data_ptr<int>();
126	    tok.B = B;
127	    tok.workspace = sc.workspace.data_ptr<float>();
128	    tok.loss_out = loss_dev.data_ptr<float>();
129	
130	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
131	    cudaError_t err = ::sg::fused::sm90::launch_fused_mamba_megakernel_tc<OptId::AdamW>(
132	        ctx, params.data_ptr<float>(), tok, grad.data_ptr<float>(),
133	        (float)lr, (int)step, st, stream, nCTA);
134	    TORCH_CHECK(err == cudaSuccess, "TC mamba megakernel launch failed: ", cudaGetErrorString(err));
135	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
136	
137	    return {loss_dev.to(torch::kCPU), grad};
138	}
