147	static std::vector<torch::Tensor> tc_dump_ff2_operands(torch::Tensor params, int64_t B) {
148	    const int nCTA = tc_effective_nctas(params, 0);  // unused for offsets; acts layout is nCTA-independent
149	    (void)nCTA;
150	    TcScratch& sc = tc_scratch_for(params, (int)B, tc_effective_nctas(params, 4));
151	    const int T = (int)B * dec::kSeq;
152	    const int64_t d = dec::kD, dff = dec::kDff;
153	    auto acts_bf16 = sc.workspace.slice(0, 0, ::sg::fused::sm90::dec_tc_acts_floats(T, (int)B))
154	                         .view(torch::kBFloat16);
155	    // mirror dec_acts_bind: walk to dY_ff2[1] and X_gact[1].
156	    const int64_t Td = (int64_t)T * d, T3d = (int64_t)T * 3 * d, Tff = (int64_t)T * dff;
157	    int64_t off = 0; int64_t off_Xgact1 = -1, off_dYff2_1 = -1;
158	    for (int li = 0; li < dec::kLayers; ++li) {
159	        off += Td;          // X_in
160	        off += Td;          // X_ctx
161	        off += Td;          // X_x1
162	        if (li == 1) off_Xgact1 = off;
163	        off += Tff;         // X_gact
164	        off += T3d;         // dY_qkv
165	        off += Td;          // dY_a
166	        off += Tff;         // dY_ff0
167	        if (li == 1) off_dYff2_1 = off;
168	        off += Td;          // dY_ff2
169	    }
170	    auto Xgact1 = acts_bf16.slice(0, off_Xgact1, off_Xgact1 + Tff).to(torch::kFloat32).to(torch::kCPU);
171	    auto dYff2_1 = acts_bf16.slice(0, off_dYff2_1, off_dYff2_1 + Td).to(torch::kFloat32).to(torch::kCPU);

237	PYBIND11_MODULE(TORCH_EXTENSION_NAME, mm) {
238	    mm.def("tc_train_step", &tc_train_step,
239	           "Fork-B tensor-core mamba fwd+bwd+AdamW step (in place); returns (loss, reduced grad)",
240	           pybind11::arg("params"), pybind11::arg("tokens"), pybind11::arg("targets"),
241	           pybind11::arg("state"), pybind11::arg("lr"), pybind11::arg("beta1"),
242	           pybind11::arg("beta2"), pybind11::arg("eps"), pybind11::arg("weight_decay"),
243	           pybind11::arg("bc1"), pybind11::arg("bc2"), pybind11::arg("step"),
244	           pybind11::arg("ncta_cap") = 0);
245	    mm.def("tc_dump_outproj_operands", &tc_dump_outproj_operands,
246	           "gate-only: dump the kernel's stored dY_dyout[L1], X_ygated[L1] (fp32 CPU)");
247	#if SG_MB_SCALAR_MEGAKERNEL
248	    mm.def("scalar_train_step", &scalar_train_step,
249	           "gate-only: SAME cell via the SCALAR launcher (back-to-back step-time mirror)",
250	           pybind11::arg("params"), pybind11::arg("tokens"), pybind11::arg("targets"),
251	           pybind11::arg("state"), pybind11::arg("lr"), pybind11::arg("beta1"),
252	           pybind11::arg("beta2"), pybind11::arg("eps"), pybind11::arg("weight_decay"),
253	           pybind11::arg("bc1"), pybind11::arg("bc2"), pybind11::arg("step"));
254	#endif  // SG_MB_SCALAR_MEGAKERNEL
255	    mm.attr("TILE_M") = (int)mbtc::kTileM;
256	    mm.attr("TILE_N") = (int)SG_TUNED_TILE_N;
257	    mm.attr("TOTAL") = (int)kMambaTotalElems;
258	    // Compiled-width introspection (the d-scaled bench asserts/reports these).
